"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["80644"],{34(n){n.exports=JSON.parse('{"id":"FIN-1250","slug":"economic-sanctions","term":"Economic Sanctions","also_known_as":[],"difficulty":"Advanced","definition":"Economic sanctions are restrictions imposed by one or more countries on another country, organisation or individual, limiting trade, investment or financial transactions, usually to pressure them to change their behaviour.","explanation":["Sanctions are used as a tool of foreign policy, often in response to military aggression, human rights abuses, terrorism, nuclear weapons programmes or other actions considered threatening.","They can take many forms, including bans on imports or exports of certain goods, freezing assets held abroad, restricting access to the international financial system, banning investment, and targeting specific individuals or companies with travel bans and asset freezes.","For example, after Russia\'s invasion of Ukraine in 2022, many countries froze Russian central bank reserves held abroad, restricted major Russian banks from the SWIFT payment messaging system and limited trade in key goods.","Sanctions can impose significant costs on targeted economies, but their effectiveness in changing behaviour is debated. Targets may find ways around them, and sanctions can hurt ordinary citizens and businesses in both the targeted and sanctioning countries. Banks and companies must screen transactions carefully to comply, since breaches can lead to heavy penalties."],"note":"","total":1500,"prev":{"slug":"economic-rent","term":"Economic Rent"},"next":{"slug":"economics","term":"Economics"}}')}}]);